#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<int>> rev(n + 1);
    vector<int> remaining(n + 1, 0);
    for (const vector<long long>& e : edges) {
        rev[e[1]].push_back((int)e[0]);
        remaining[e[0]]++;
    }
    vector<int> queue;
    for (int v = 1; v <= n; v++) {
        if (remaining[v] == 0) queue.push_back(v);
    }
    for (size_t i = 0; i < queue.size(); i++) {
        for (int u : rev[queue[i]]) {
            remaining[u]--;
            if (remaining[u] == 0) queue.push_back(u);
        }
    }
    sort(queue.begin(), queue.end());
    if (queue.empty()) cout << "none";
    for (size_t i = 0; i < queue.size(); i++) cout << (i ? " " : "") << queue[i];
    cout << "\n";

    return 0;
}

