import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[][] edges = new long[(int) m][2];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }

        int nodes = (int) n;
        List<List<Integer>> rev = new ArrayList<>();
        for (int v = 0; v <= nodes; v++) rev.add(new ArrayList<>());
        int[] remaining = new int[nodes + 1];
        for (long[] e : edges) {
            rev.get((int) e[1]).add((int) e[0]);
            remaining[(int) e[0]]++;
        }
        List<Integer> queue = new ArrayList<>();
        for (int v = 1; v <= nodes; v++) {
            if (remaining[v] == 0) queue.add(v);
        }
        for (int i = 0; i < queue.size(); i++) {
            for (int u : rev.get(queue.get(i))) {
                remaining[u]--;
                if (remaining[u] == 0) queue.add(u);
            }
        }
        Collections.sort(queue);
        if (queue.isEmpty()) {
            System.out.println("none");
        } else {
            StringBuilder out = new StringBuilder();
            for (int i = 0; i < queue.size(); i++) out.append(i > 0 ? " " : "").append(queue.get(i));
            System.out.println(out);
        }
    }
}
